/usr/bin/zsh -lc "cd /home/mato/.cache/real-chart-bench/codex-local/work/pixcal/qwen3.8-27b/part2 && cat > drawpred.py << 'EOF'
import lib, json, sys
import numpy as np
from PIL import Image, ImageDraw
d=json.load(open('results.json'))
names=sys.argv[1:] if len(sys.argv)>1 else list(d)
for fig in names:
    t=lib.TASKS[fig]
    def inv(pv, p1,v1,p2,v2,scale):
        if scale=='log':
            lv=np.log10(v1)+(pv-p1)*(np.log10(v2)-np.log10(v1))/(p2-p1)
            return 10**lv
        return v1+(pv-p1)*(v2-v1)/(p2-p1)
    # invert: given value -> pixel
    def v2px(val, p1,v1,p2,v2,scale):
        if scale=='log':
            return p1+(np.log10(val)-np.log10(v1))*(p2-p1)/(np.log10(v2)-np.log10(v1))
        return p1+(val-v1)*(p2-p1)/(v2-v1)
    im=Image.open('images/'+fig).convert('RGB'); W,H=im.size
    im=im.resize((W*2,H*2),Image.NEAREST); dr=ImageDraw.Draw(im)
    cols=['magenta','lime','cyan','orange','yellow','red']
    for k,s in enumerate(d[fig]):
        xs=lib.TASKS[fig]['x_ticks']; ys=lib.TASKS[fig]['y_ticks']
        for xv,yv in zip(s['x'],s['y']):
            px=v2px(xv, xs[0]['pixel_x'],xs[0]['value'],xs[1]['pixel_x'],xs[1]['value'], t['x_scale'])*2
            py=v2px(yv, ys[0]['pixel_y'],ys[0]['value'],ys[1]['pixel_y'],ys[1]['value'], t['y_scale'])*2
            c=cols[k%6]
            dr.ellipse([px-8,py-8,px+8,py+8],outline=c,width=3)
    im.save('/tmp/pred_'+fig)
print('ok')
