import numpy as np
from lib import load
im=load('fig_055.png')
r=im[:,:,0].astype(int); g=im[:,:,1].astype(int); b=im[:,:,2].astype(int)
red=((r-g)>35)&((r-b)>35)
blk=(im.max(axis=2)<=170)&((im.max(axis=2)-im.min(axis=2))<=90)
white=(im.min(axis=2)>185)
H,W=red.shape

def tri_ring(s=6):
    ring=[];center=[]
    for dy in range(-s,s+1):
        w=int(round(s*(dy+s)/(2*s)))
        for dx in range(-w,w+1):
            if abs(dx)>=w or dy>=s or dy<=-s: ring.append((dx,dy))
            if abs(dx)<=2 and -1<=dy<=3: center.append((dx,dy))
    return ring,center
def sq_ring(s=5):
    ring=[];center=[]
    for dy in range(-s,s+1):
        for dx in range(-s,s+1):
            if abs(dx)==s or abs(dy)==s: ring.append((dx,dy))
            if abs(dx)<=2 and abs(dy)<=2: center.append((dx,dy))
    return ring,center

def score(cx,cy,ring,center,ok,bad):
    hit=0;wrong=0;cw=0
    for dx,dy in ring:
        x=cx+dx;y=cy+dy
        if 0<=x<W and 0<=y<H:
            if ok[y,x]: hit+=1
            elif bad[y,x]: wrong+=1
    for dx,dy in center:
        x=cx+dx;y=cy+dy
        if 0<=x<W and 0<=y<H and white[y,x]: cw+=1
    return hit-1.3*wrong+0.5*cw

tr=tri_ring(6); sr=sq_ring(5)
def scan(ring,center,ok,bad,step=2,thr=14):
    cands=[]
    for cy in range(100,470,step):
        for cx in range(116,706,step):
            s=score(cx,cy,ring,center,ok,bad)
            if s>thr: cands.append((s,cx,cy))
    cands.sort(reverse=True)
    kept=[]
    for s,cx,cy in cands:
        if all((cx-kx)**2+(cy-ky)**2>9**2 for _,kx,ky in kept):
            kept.append((s,cx,cy))
    return sorted(kept,key=lambda t:t[1])

rres=scan(*tr,red,blk)
bres=scan(*sr,blk,red)
